BEGIN;
-- Run in a transaction. One timed statement bounds the whole schema operation.
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $cmpri_boundary$ BEGIN EXECUTE $cmpri_sql$
-- LOCAL ONLY: approved coordinated cutover required. All catalog originals retained.
SET LOCAL cmpri.unassigned_documents='retain';
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
SET LOCAL TIME ZONE 'UTC';
DO $$ BEGIN
 IF current_setting('cmpri.unassigned_documents',true) IS NULL OR current_setting('cmpri.unassigned_documents',true) NOT IN ('retain','archive') THEN
  RAISE EXCEPTION 'Unassigned-document decision is required';
 END IF;
 IF EXISTS(SELECT 1 FROM public.assets WHERE hotel_id <> 'c81ad01a-7a9f-4880-ac1c-5e849f30bad6') OR EXISTS(SELECT 1 FROM public.maintenance_documents WHERE hotel_id <> 'c81ad01a-7a9f-4880-ac1c-5e849f30bad6') THEN RAISE EXCEPTION 'CMPRI-only migration'; END IF;
 IF EXISTS(SELECT 1 FROM public.assets a JOIN public.maintenance_documents d USING(id)) THEN RAISE EXCEPTION 'Identifier collision'; END IF;
END $$;
