CREATE SCHEMA cmpri_consolidation_rollback;
REVOKE ALL ON SCHEMA cmpri_consolidation_rollback FROM PUBLIC, anon, authenticated, service_role;
CREATE TABLE cmpri_consolidation_rollback.assets AS TABLE public.assets;
ALTER TABLE cmpri_consolidation_rollback.assets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.maintenance_documents SET SCHEMA cmpri_consolidation_rollback;
REVOKE ALL ON cmpri_consolidation_rollback.maintenance_documents FROM PUBLIC,anon,authenticated,service_role;
ALTER TABLE public.assets RENAME TO cmpri_assets_and_pdfs;
-- Renaming preserves the original table OID: every ticket/PM/Enseo FK stays attached.
ALTER TABLE public.cmpri_assets_and_pdfs
 ADD COLUMN record_kind text NOT NULL DEFAULT 'asset' CHECK(record_kind IN ('asset','document')),
 ADD COLUMN pdf_import_links jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(pdf_import_links)='array'),
 ADD COLUMN pdf_import_history jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(pdf_import_history)='array'),
 ADD COLUMN catalog_record jsonb;
ALTER TABLE public.cmpri_assets_and_pdfs ADD CONSTRAINT cmpri_record_shape CHECK(
 (record_kind='asset' AND catalog_record IS NULL) OR
 (record_kind='document' AND jsonb_typeof(catalog_record)='object' AND catalog_record->>'id'=id::text AND catalog_record->>'hotel_id'=hotel_id::text));
CREATE UNIQUE INDEX cmpri_catalog_document_key ON public.cmpri_assets_and_pdfs(hotel_id,(catalog_record->>'document_key')) WHERE record_kind='document';
ALTER TABLE public.cmpri_assets_and_pdfs DISABLE TRIGGER cmpri_protect_verified_asset;
ALTER TABLE public.cmpri_assets_and_pdfs DISABLE TRIGGER trg_assets_updated_at;
