INSERT INTO public.cmpri_assets_and_pdfs(id,hotel_id,asset_type,name,manufacturer,active,created_at,updated_at,record_kind,catalog_record)
 SELECT d.id,d.hotel_id,'document',d.title,coalesce(d.manufacturer,''),d.active,d.created_at,d.updated_at,'document',to_jsonb(d)
 FROM cmpri_consolidation_rollback.maintenance_documents d
 WHERE current_setting('cmpri.unassigned_documents')='retain' OR d.document_key NOT IN ('boh-dryer-utf75ruf6a2w01','cmpri-television-troubleshooting-guide','cmpri-front-desk-troubleshooting-guide','navien-npe-parts-list','curtis-coffee-server-parts','alliance-laundry-systems-llc-parts-washer-extractor-pocket-hardmount','ge-thermostat-wiring-diagram','unimac-uwn065t4v-troubleshooting','ge-zoneline-az95-service-guide','alliance-laundry-systems-llc-washer-extractor-pocket-hardmount-parts','verdant-vx-tr-kt-w-installation-manual','unimac-uwn065t4v-quick-troubleshooting','cmpri-brand-sign-led-installation','cmpri-guest-room-troubleshooting-guide');
ALTER TABLE public.cmpri_assets_and_pdfs ENABLE TRIGGER cmpri_protect_verified_asset;
ALTER TABLE public.cmpri_assets_and_pdfs ENABLE TRIGGER trg_assets_updated_at;
CREATE VIEW public.assets WITH(security_invoker=true) AS SELECT pdf_import_links,pdf_import_history,"id", "hotel_id", "location_id", "legacy_asset_id", "asset_type", "name", "manufacturer", "model", "serial_number", "active", "notes", "created_at", "updated_at", "asset_tag", "status", "installed_on", "purchase_cost", "replacement_cost", "warranty_expires_on", "model_number", "generation", "install_year", "documentation_key", "binder_import_id", "binder_category", "binder_location", "location_class", "room_type", "quantity", "binder_tag", "mapping_method", "source_page", "source_file", "import_status", "review_note", "binder_source_locked", "model_family", "documentation_verified_at", "documentation_verified_by", "documentation_revision_id" FROM public.cmpri_assets_and_pdfs WHERE record_kind='asset' WITH LOCAL CHECK OPTION;
GRANT SELECT ON public.assets TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.assets TO service_role;
CREATE VIEW public.maintenance_documents WITH(security_invoker=true) AS
 SELECT (catalog_record->>'id')::uuid AS "id",
 (catalog_record->>'hotel_id')::uuid AS "hotel_id",
 (catalog_record->>'document_key')::text AS "document_key",
 (catalog_record->>'title')::text AS "title",
 (catalog_record->>'document_type')::text AS "document_type",
 (catalog_record->>'manufacturer')::text AS "manufacturer",
 (catalog_record->>'equipment')::text AS "equipment",
 (catalog_record->>'model_pattern')::text AS "model_pattern",
 (catalog_record->>'drive_file_id')::text AS "drive_file_id",
 (catalog_record->>'drive_url')::text AS "drive_url",
 (catalog_record->>'storage_path')::text AS "storage_path",
 (catalog_record->>'troubleshooting_cache_key')::text AS "troubleshooting_cache_key",
 (catalog_record->>'active')::bool AS "active",
 (catalog_record->>'created_at')::timestamptz AS "created_at",
 (catalog_record->>'updated_at')::timestamptz AS "updated_at",
 (catalog_record->>'ingestion_status')::text AS "ingestion_status",
 (catalog_record->>'ingestion_error')::text AS "ingestion_error",
 (catalog_record->>'ingested_at')::timestamptz AS "ingested_at",
 (catalog_record->>'knowledge_version')::int4 AS "knowledge_version",
 (catalog_record->>'source_file_name')::text AS "source_file_name"
 FROM public.cmpri_assets_and_pdfs WHERE record_kind='document';
GRANT SELECT ON public.maintenance_documents TO authenticated,service_role;
COMMENT ON TABLE public.cmpri_assets_and_pdfs IS 'One authoritative CMPRI-local physical table for assets, PDF pointers and catalog documents. Asset IDs and inbound FK OIDs preserved. Legacy snapshots are frozen in cmpri_consolidation_rollback.';
CREATE FUNCTION cmpri_consolidation_rollback.reject_write() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'Read-only consolidation rollback snapshot'; END $$;
REVOKE ALL ON FUNCTION cmpri_consolidation_rollback.reject_write() FROM PUBLIC;
CREATE TRIGGER freeze_snapshot BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON cmpri_consolidation_rollback.assets FOR EACH STATEMENT EXECUTE FUNCTION cmpri_consolidation_rollback.reject_write();
CREATE TRIGGER freeze_snapshot BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON cmpri_consolidation_rollback.maintenance_documents FOR EACH STATEMENT EXECUTE FUNCTION cmpri_consolidation_rollback.reject_write();
CREATE OR REPLACE FUNCTION public.cmpri_verify_asset_documentation(p_asset_id uuid, p_hotel_id uuid, p_expected_updated_at timestamp with time zone, p_actor_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.cmpri_assets_and_pdfs; verified_at timestamptz;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service role required'; end if;
 if p_asset_id is null or p_hotel_id is null or p_expected_updated_at is null or p_actor_id is null then raise exception 'Complete equipment verification details are required'; end if;
 select * into a from public.cmpri_assets_and_pdfs where id=p_asset_id and hotel_id=p_hotel_id and record_kind='asset' for update;
 if not found then raise exception 'Equipment not found'; end if;
 if a.documentation_verified_at is not null then return a.documentation_verified_at; end if;
 if a.updated_at is distinct from p_expected_updated_at then raise exception 'Equipment changed during documentation verification'; end if;
 update public.cmpri_assets_and_pdfs set documentation_verified_at=clock_timestamp(), documentation_verified_by=p_actor_id,documentation_revision_id=null
 where id=p_asset_id and hotel_id=p_hotel_id returning documentation_verified_at into verified_at;
 if a.documentation_revision_id is not null then
  update public.cmpri_equipment_document_revisions set closed_at=verified_at,
   verified_asset=(select to_jsonb(current_asset) from public.cmpri_assets_and_pdfs current_asset where id=p_asset_id)
  where id=a.documentation_revision_id and closed_at is null;
 end if;
 return verified_at;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.cmpri_begin_equipment_revision(p_asset_id uuid, p_hotel_id uuid, p_expected_updated_at timestamp with time zone, p_actor_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.cmpri_assets_and_pdfs; revision_id uuid; documents jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service role required'; end if;
 if p_expected_updated_at is null or p_reason is null or char_length(trim(p_reason)) not between 5 and 2000 then raise exception 'A current record and revision reason are required'; end if;
 if not exists(select 1 from public.profiles p join public.hotel_members m on m.user_id=p.id
   where p.id=p_actor_id and p.active and m.hotel_id=p_hotel_id and m.active
   and regexp_replace(lower(p.role::text),'[^a-z]','','g') in
    ('engineer','engineers','engineering','chiefengineer','engineeringmanager','regionalmaintenance','regionalengineer','systemadmin','sysadmin','systemadministrator','administrator','admin')) then
  raise exception 'Active equipment editor required';
 end if;
 select * into a from public.cmpri_assets_and_pdfs where id=p_asset_id and hotel_id=p_hotel_id and record_kind='asset' for update;
 if not found or a.updated_at is distinct from p_expected_updated_at or a.documentation_verified_at is null or a.documentation_revision_id is not null then
  raise exception 'Verified equipment changed; reload before revising';
 end if;
 select a.pdf_import_links into documents;
 insert into public.cmpri_equipment_document_revisions(hotel_id,asset_id,actor_id,reason,prior_asset,prior_documents)
 values(p_hotel_id,p_asset_id,p_actor_id,trim(p_reason),to_jsonb(a),documents) returning id into revision_id;
 update public.cmpri_assets_and_pdfs set documentation_verified_at=null,documentation_verified_by=null,documentation_revision_id=revision_id
 where id=p_asset_id and hotel_id=p_hotel_id;
 return revision_id;
end;
$function$
;
CREATE FUNCTION public.cmpri_list_asset_files(p_asset_id uuid)
RETURNS TABLE(id uuid,name text,storage_path text,created_at timestamptz,updated_at timestamptz,preferred boolean)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT (l->>'object_id')::uuid,regexp_replace(l->>'storage_path','^.*/',''),l->>'storage_path',
 (l->'original_object'->>'created_at')::timestamptz,(l->'original_object'->>'updated_at')::timestamptz,coalesce((l->>'preferred')::boolean,false)
 FROM public.cmpri_assets_and_pdfs a CROSS JOIN LATERAL jsonb_array_elements(a.pdf_import_links) l
 WHERE a.id=p_asset_id AND a.record_kind='asset' AND a.hotel_id='c81ad01a-7a9f-4880-ac1c-5e849f30bad6' AND l->>'storage_path' IS NOT NULL
 ORDER BY coalesce((l->>'preferred')::boolean,false) DESC,l->>'storage_path';
$$;
REVOKE ALL ON FUNCTION public.cmpri_list_asset_files(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.cmpri_list_asset_files(uuid) TO authenticated,service_role;

CREATE FUNCTION public.cmpri_register_asset_file(p_asset_id uuid,p_storage_path text)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE a public.cmpri_assets_and_pdfs; obj storage.objects; newlink jsonb;
BEGIN
 SELECT * INTO a FROM public.cmpri_assets_and_pdfs WHERE id=p_asset_id AND record_kind='asset' AND hotel_id='c81ad01a-7a9f-4880-ac1c-5e849f30bad6' FOR UPDATE;
 IF NOT FOUND OR p_storage_path IS NULL OR p_storage_path NOT LIKE a.hotel_id::text||'/'||a.id::text||'/%' OR p_storage_path LIKE '%/../%' THEN RAISE EXCEPTION 'Invalid CMPRI asset file'; END IF;
 SELECT * INTO obj FROM storage.objects WHERE bucket_id='asset-documentation' AND name=p_storage_path;
 IF NOT FOUND THEN RAISE EXCEPTION 'Stored original is missing'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(a.pdf_import_links) l WHERE l->>'object_id'=obj.id::text) THEN RETURN; END IF;
 IF a.documentation_verified_at IS NOT NULL THEN RAISE EXCEPTION 'Open an equipment revision first'; END IF;
 newlink:=jsonb_build_object('object_id',obj.id,'storage_path',obj.name,'object_version',obj.version,'etag',obj.metadata->>'eTag','size',coalesce((obj.metadata->>'size')::bigint,0),'title',regexp_replace(obj.name,'^.*/',''),'manufacturer','','models','[]'::jsonb,'selected_model','','applicability','reference','notes','','reason','Existing importer original','extracted_fields','{}'::jsonb,'preferred',false,'original_object',to_jsonb(obj));
 UPDATE public.cmpri_assets_and_pdfs SET pdf_import_links=a.pdf_import_links||jsonb_build_array(newlink),pdf_import_history=a.pdf_import_history||jsonb_build_array(jsonb_build_object('event','original_registered','before',a.pdf_import_links,'after',a.pdf_import_links||jsonb_build_array(newlink))) WHERE id=a.id;
END $$;
REVOKE ALL ON FUNCTION public.cmpri_register_asset_file(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cmpri_register_asset_file(uuid,text) TO service_role;

CREATE FUNCTION public.cmpri_upsert_asset_catalog(p_asset_id uuid,p_record jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE a public.cmpri_assets_and_pdfs; d public.cmpri_assets_and_pdfs; doc jsonb; doc_id uuid; key text; next_links jsonb;
BEGIN
 SELECT * INTO a FROM public.cmpri_assets_and_pdfs WHERE id=p_asset_id AND record_kind='asset' AND hotel_id='c81ad01a-7a9f-4880-ac1c-5e849f30bad6' FOR UPDATE;
 IF NOT FOUND OR p_record->>'hotel_id' IS DISTINCT FROM a.hotel_id::text THEN RAISE EXCEPTION 'Invalid CMPRI asset'; END IF;
 key:=p_record->>'document_key';
 IF key IS NULL OR key NOT LIKE 'upload-'||a.id::text||'-%' THEN RAISE EXCEPTION 'Only asset-owned catalog records may be written'; END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.pdf_import_links) l WHERE l->>'storage_path'=p_record->>'storage_path') THEN RAISE EXCEPTION 'Register the original first'; END IF;
 SELECT * INTO d FROM public.cmpri_assets_and_pdfs WHERE record_kind='document' AND hotel_id=a.hotel_id AND catalog_record->>'document_key'=key FOR UPDATE;
 doc_id:=coalesce(d.id,gen_random_uuid());
 doc:=coalesce(d.catalog_record,jsonb_build_object('id',doc_id,'hotel_id',a.hotel_id,'document_key',key,'created_at',now(),'updated_at',now(),'active',true,'ingestion_status','pending','knowledge_version',1,'ingested_at',null,'drive_file_id',null,'drive_url',null))||p_record||jsonb_build_object('id',doc_id,'hotel_id',a.hotel_id,'document_key',key);
 IF d.id IS NULL THEN
  INSERT INTO public.cmpri_assets_and_pdfs(id,hotel_id,record_kind,asset_type,name,manufacturer,catalog_record) VALUES(doc_id,a.hotel_id,'document','document',coalesce(doc->>'title',''),coalesce(doc->>'manufacturer',''),doc);
 ELSE
  UPDATE public.cmpri_assets_and_pdfs SET catalog_record=doc,pdf_import_history=pdf_import_history||jsonb_build_array(jsonb_build_object('event','catalog_update','before',d.catalog_record,'after',doc)),name=coalesce(doc->>'title',''),manufacturer=coalesce(doc->>'manufacturer','') WHERE id=doc_id;
 END IF;
 SELECT jsonb_agg(CASE WHEN l->>'storage_path'=p_record->>'storage_path' THEN l||jsonb_build_object('document_id',doc_id,'document_key',key) ELSE l END) INTO next_links FROM jsonb_array_elements(a.pdf_import_links) l;
 IF next_links IS DISTINCT FROM a.pdf_import_links THEN
 UPDATE public.cmpri_assets_and_pdfs SET pdf_import_links=next_links,pdf_import_history=a.pdf_import_history||jsonb_build_array(jsonb_build_object('event','catalog_registered','before',a.pdf_import_links,'after',next_links)) WHERE id=a.id;
 END IF;
 RETURN doc_id;
END $$;
REVOKE ALL ON FUNCTION public.cmpri_upsert_asset_catalog(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cmpri_upsert_asset_catalog(uuid,jsonb) TO service_role;

DO $$ BEGIN
 IF (SELECT count(*) FROM public.assets)<>2389 OR (SELECT count(*) FROM public.maintenance_documents)<>25 THEN RAISE EXCEPTION 'Preservation counts differ'; END IF;
 IF EXISTS((SELECT to_jsonb(a)-'pdf_import_links'-'pdf_import_history' FROM public.assets a EXCEPT ALL SELECT to_jsonb(a) FROM cmpri_consolidation_rollback.assets a) UNION ALL (SELECT to_jsonb(a) FROM cmpri_consolidation_rollback.assets a EXCEPT ALL SELECT to_jsonb(a)-'pdf_import_links'-'pdf_import_history' FROM public.assets a)) THEN RAISE EXCEPTION 'Asset fields changed'; END IF;
 END $$;
NOTIFY pgrst,'reload schema';

CREATE FUNCTION public.cmpri_import_stored_pdfs()
RETURNS TABLE(object_id uuid,storage_path text,object_version text,etag text,size bigint,title text)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT o.id,o.name,o.version,o.metadata->>'eTag',coalesce((o.metadata->>'size')::bigint,0),coalesce(d.title,regexp_replace(o.name,'^.*/',''))
 FROM storage.objects o LEFT JOIN public.maintenance_documents d ON d.storage_path=o.name AND d.hotel_id='c81ad01a-7a9f-4880-ac1c-5e849f30bad6'
 WHERE o.bucket_id='asset-documentation' AND lower(o.name) LIKE '%.pdf'
 AND (o.name LIKE 'Asset Docs/%' OR EXISTS(SELECT 1 FROM public.cmpri_assets_and_pdfs a WHERE a.hotel_id='c81ad01a-7a9f-4880-ac1c-5e849f30bad6' AND o.name LIKE a.hotel_id::text||'/'||a.id::text||'/%'))
 ORDER BY o.name;
$$;
REVOKE ALL ON FUNCTION public.cmpri_import_stored_pdfs() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cmpri_import_stored_pdfs() TO service_role;

CREATE FUNCTION public.cmpri_save_import_pdf_link(p_asset_id uuid,p_expected_updated_at timestamptz,p_actor_id uuid,p_link jsonb,p_remove boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE a public.cmpri_assets_and_pdfs; obj record; next_links jsonb; saved jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required'; END IF;
 IF p_actor_id IS NULL OR p_link->>'object_id' IS NULL OR length(trim(coalesce(p_link->>'reason',''))) NOT BETWEEN 5 AND 2000 THEN RAISE EXCEPTION 'Actor, document and correction reason are required'; END IF;
 SELECT * INTO a FROM public.cmpri_assets_and_pdfs WHERE id=p_asset_id AND hotel_id='c81ad01a-7a9f-4880-ac1c-5e849f30bad6' FOR UPDATE;
 IF NOT FOUND OR a.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'Equipment changed. Reload before saving associations'; END IF;
 IF a.documentation_verified_at IS NOT NULL THEN RAISE EXCEPTION 'Open an equipment revision before changing verified associations'; END IF;
 IF p_remove THEN
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.pdf_import_links) l WHERE l->>'object_id'=p_link->>'object_id') THEN RAISE EXCEPTION 'The selected association no longer exists'; END IF;
 ELSE
  SELECT * INTO obj FROM public.cmpri_import_stored_pdfs() WHERE object_id=(p_link->>'object_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Stored PDF is missing'; END IF;
  IF obj.size=0 THEN RAISE EXCEPTION 'Stored PDF is empty'; END IF;
  IF obj.storage_path IS DISTINCT FROM p_link->>'storage_path' OR obj.object_version IS DISTINCT FROM p_link->>'object_version' OR obj.etag IS DISTINCT FROM p_link->>'etag' OR obj.size IS DISTINCT FROM (p_link->>'size')::bigint THEN RAISE EXCEPTION 'Stored PDF changed since review'; END IF;
  IF coalesce(p_link->>'sha256','') !~ '^[a-f0-9]{64}$' OR coalesce(p_link->>'applicability','') NOT IN ('reference','confirmed_model') THEN RAISE EXCEPTION 'Verified file hash and applicability are required'; END IF;
 END IF;
 SELECT coalesce(jsonb_agg(CASE WHEN NOT p_remove AND p_link->>'preferred'='true' THEN l||'{"preferred":false}'::jsonb ELSE l END),'[]'::jsonb) INTO next_links FROM jsonb_array_elements(a.pdf_import_links) l WHERE l->>'object_id' IS DISTINCT FROM p_link->>'object_id';
 saved:=coalesce((SELECT l FROM jsonb_array_elements(a.pdf_import_links) l WHERE l->>'object_id'=p_link->>'object_id'),'{}'::jsonb)||p_link||jsonb_build_object('saved_by',p_actor_id,'saved_at',clock_timestamp());
 IF NOT p_remove THEN next_links:=next_links||jsonb_build_array(saved); END IF;
 UPDATE public.cmpri_assets_and_pdfs SET pdf_import_links=next_links,pdf_import_history=pdf_import_history||jsonb_build_array(jsonb_build_object('actor_id',p_actor_id,'at',clock_timestamp(),'reason',p_link->>'reason','before',a.pdf_import_links,'after',next_links)) WHERE id=a.id;
 RETURN jsonb_build_object('links',next_links,'updated_at',(SELECT updated_at FROM public.cmpri_assets_and_pdfs WHERE id=a.id));
END $$;
REVOKE ALL ON FUNCTION public.cmpri_save_import_pdf_link(uuid,timestamptz,uuid,jsonb,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cmpri_save_import_pdf_link(uuid,timestamptz,uuid,jsonb,boolean) TO service_role;

CREATE FUNCTION public.cmpri_consolidation_ready() RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT true $$;
REVOKE ALL ON FUNCTION public.cmpri_consolidation_ready() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cmpri_consolidation_ready() TO service_role;
CREATE TABLE cmpri_consolidation_rollback.cutover_state AS TABLE public.cmpri_assets_and_pdfs;
ALTER TABLE cmpri_consolidation_rollback.cutover_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON cmpri_consolidation_rollback.cutover_state FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER freeze_snapshot BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON cmpri_consolidation_rollback.cutover_state FOR EACH STATEMENT EXECUTE FUNCTION cmpri_consolidation_rollback.reject_write();

$cmpri_sql$; END $cmpri_boundary$;

COMMIT;